-- Private catalog + typed data copies. Never overwrites an existing backup.
BEGIN;
SET LOCAL lock_timeout='10s';
LOCK TABLE public.quadro_pessoal_alocacao,public.quadro_pessoal_movimentos,public.quadro_equipa_permanencias,public.quadro_dias_revisoes,public.quadro_operacoes,public.quadro_escrita_interna,public.folha_registos,public.folha_historico,public.folha_externos,public.folha_externos_dias,public.folha_externos_permanencias,public.folha_horarios,public.folha_config_empresa,public.folha_he,public.folha_vencimentos,public.folha_tarefas_reportes,public.folha_gestao_historico,public.ponto_pessoal_obra,public.colaboradores,public.utilizadores,public.obras,public.ausencias,folha_privado.operacoes,folha_privado.equipa_revisoes,folha_privado.periodos_revisoes,folha_privado.legacy_cutover,primeline_quadro_rollout.controlo IN ACCESS EXCLUSIVE MODE;
DO $check$
DECLARE f record; t text; role_name text;
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED' USING ERRCODE='42501'; END IF;
 IF (SELECT count(*) FROM primeline_quadro_rollout.controlo)<>1 OR (SELECT estado FROM primeline_quadro_rollout.controlo WHERE singleton) IS DISTINCT FROM 'a' THEN RAISE EXCEPTION 'PHASE_A_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.quadro_pessoal_alocacao'::regclass AND tgname='trg_00_quadro_proteger_escrita' AND tgfoid='public.fn_quadro_proteger_escrita()'::regprocedure AND tgtype=31 AND tgenabled='O') OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.quadro_pessoal_alocacao'::regclass AND NOT tgisinternal AND tgenabled NOT IN('O','A')) THEN RAISE EXCEPTION 'GUARD_TRIGGER_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.quadro_pessoal_alocacao'::regclass AND polname='encarregado_sem_dml_direto' AND NOT polpermissive AND polcmd='*' AND pg_get_expr(polqual,polrelid)='(NOT fn_encarregado_acesso_direto_bloqueado())' AND pg_get_expr(polwithcheck,polrelid)='(NOT fn_encarregado_acesso_direto_bloqueado())') THEN RAISE EXCEPTION 'ENCARREGADO_RESTRICTIVE_POLICY_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM public.quadro_escrita_interna) THEN RAISE EXCEPTION 'INTERNAL_WRITE_MARKER_PRESENT'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.ponto_pessoal_obra'::regclass AND tgname='trg_01_folha_legacy_closed' AND tgenabled='O' AND tgfoid=to_regprocedure('folha_privado.legacy_closed()')) THEN RAISE EXCEPTION 'LEGACY_NOT_CLOSED'; END IF;
 IF EXISTS(SELECT 1 FROM (TABLE public.ponto_pessoal_obra EXCEPT ALL TABLE folha_privado.legacy_cutover) x) OR EXISTS(SELECT 1 FROM (TABLE folha_privado.legacy_cutover EXCEPT ALL TABLE public.ponto_pessoal_obra) x) THEN RAISE EXCEPTION 'LEGACY_DATA_DRIFT'; END IF;
