 ) x(signature,sha256,metadata) LOOP
  IF to_regprocedure(f.signature) IS NULL OR (SELECT encode(sha256(convert_to(replace(pg_get_functiondef(to_regprocedure(f.signature)),chr(13),''),'UTF8')),'hex')) IS DISTINCT FROM f.sha256 THEN RAISE EXCEPTION 'CURRENT_CONTRACT_DRIFT: %',f.signature; END IF;
  IF (SELECT jsonb_build_object('owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,pg_get_userbyid(a.grantor),a.is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) FROM pg_proc p WHERE p.oid=to_regprocedure(f.signature)) IS DISTINCT FROM f.metadata THEN RAISE EXCEPTION 'CURRENT_CONTRACT_DRIFT: metadata %',f.signature; END IF;
 END LOOP;
 FOR f IN SELECT p.*,p.oid::regprocedure::text signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND replace(p.prosrc,chr(13),'') ~* '(insert[[:space:]]+into|update|delete[[:space:]]+from)[[:space:]]+(public\.)?quadro_pessoal_(alocacao|movimentos)\M' LOOP
