 END LOOP;
 FOREACH t IN ARRAY ARRAY['public.quadro_pessoal_alocacao','public.quadro_pessoal_movimentos'] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=t::regclass AND relowner='postgres'::regrole AND relrowsecurity) THEN RAISE EXCEPTION 'OWNER_RLS_REQUIRED: %',t; END IF;
  IF EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=t::regclass AND a.grantor<>'postgres'::regrole)
